const { existsSync, readFileSync } = await import('node:fs');
if (!globalThis.input || typeof globalThis.input.image_path !== 'string') { throw new Error('Missing required input: image_path'); }
if (!existsSync(globalThis.input.image_path)) { throw new Error('Image file not found at ' + globalThis.input.image_path); }
globalThis.imagePath = globalThis.input.image_path;
globalThis.imageData = readFileSync(globalThis.imagePath);

const pdfLibMod = await import('pdf-lib');
const { PDFDocument } = pdfLibMod.default || pdfLibMod;
const imgBytes = globalThis.imageData;
const pdfDoc = await PDFDocument.create();
let img;
if (imgBytes[0] === 0x89) {
  img = await pdfDoc.embedPng(imgBytes);
} else {
  img = await pdfDoc.embedJpg(imgBytes);
}
const page = pdfDoc.addPage([img.width, img.height]);
page.drawImage(img, { x: 0, y: 0, width: img.width, height: img.height });
const pdfBytes = await pdfDoc.save();
globalThis.pdfBase64 = Buffer.from(pdfBytes).toString('base64');
